<script>
import { adminApi } from "../../services/adminApi";
export default { data(){return {loading:true,error:"",items:[]}}, async mounted(){try{this.items=await adminApi.get("shows")}catch(e){this.error=e.response?.data?.message||"Não foi possível carregar os dados."}finally{this.loading=false}}, methods:{money(v){return Number(v||0).toLocaleString("pt-BR",{style:"currency",currency:"BRL"})},date(v){return v?new Date(v).toLocaleDateString("pt-BR"):"—"}}}
</script><template><div><h4>Shows / Contratações</h4><p class="text-muted">Visão operacional das contratações realizadas na plataforma.</p><div class="card"><div class="card-body table-responsive"><table class="table table-hover align-middle"><thead><tr><th>Data</th><th>Artista</th><th>Contratante</th><th>Evento</th><th>Local</th><th>Valor</th><th>Pagamento</th><th>Status</th></tr></thead><tbody><tr v-for="x in items" :key="x.id"><td>{{date(x.eventDate)}}</td><td><strong>{{x.artistName}}</strong></td><td>{{x.contractorName||'—'}}</td><td>{{x.title}}</td><td>{{x.city}}/{{x.state}}</td><td>{{money(x.totalProposedPrice)}}</td><td>{{x.asaasPaymentId?'Gerado':'—'}}</td><td>{{x.status}}</td></tr></tbody></table></div></div></div></template>